/*	Expire Sweep - flag offers past expiry so the next node marks them expired.	*/
const now_str = $now.toISO();
const rows_ary = $('Load Expire Rows').all().map(i_obj => i_obj.json);
const out_ary = [];
for (const r_obj of rows_ary)
{
	if (r_obj.status === 'offered' && r_obj.expires_at && DateTime.fromISO(r_obj.expires_at) < DateTime.fromISO(now_str))
	{
		out_ary.push({ json: { row_id: r_obj.id, event_id: r_obj.event_id } });
	}
}
return out_ary;

/*	Dedupe Event Ids - unique event ids from the expired rows, to re-run the offer engine.	*/
const seen_obj = {};
const out_ary = [];
for (const i_obj of $('Expire Sweep').all())
{
	const eid_str = i_obj.json.event_id;
	if (eid_str && !seen_obj[eid_str])
	{
		seen_obj[eid_str] = true;
		out_ary.push({ json: { eventId: eid_str } });
	}
}
return out_ary;

/*	Plan Offers - decides waitlist writes + which students to offer, from loaded rows.	*/
/*	Reads all rows from Load Offer Rows and events from Fetch Event; writes nothing here.	*/
/*	The email frame, button and palette live in Config, so the look changes in one place.	*/
const cfg_obj = $('Config').first().json;
const now_str = $now.toISO();
const timeout_num = Number(cfg_obj.OFFER_RESPONSE_TIMEOUT_HOURS || 0);
const step_str = cfg_obj.WAITLIST_STEP_NAME;
const rows_ary = $('Load Offer Rows').all().map(i_obj => i_obj.json);
const events_ary = $('Fetch Event').all().map(i_obj => i_obj.json);
const out_ary = [];

const esc_fn = function (v_any)
{
	return String(v_any === null || v_any === undefined ? '' : v_any)
		.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split('"').join('&quot;');
};

const pretty_fn = function (iso_str)
{
	if (!iso_str) { return ''; }
	const d_obj = new Date(String(iso_str).replace(' ', 'T'));
	if (isNaN(d_obj.getTime())) { return String(iso_str); }
	const months_ary = ['January','February','March','April','May','June','July','August','September','October','November','December'];
	return d_obj.getDate() + ' ' + months_ary[d_obj.getMonth()] + ' ' + d_obj.getFullYear();
};

const prettyTime_fn = function (iso_str)
{
	if (!iso_str) { return ''; }
	const d_obj = new Date(String(iso_str).replace(' ', 'T'));
	if (isNaN(d_obj.getTime())) { return ''; }
	const h_str = String(d_obj.getHours()).padStart(2, '0');
	const m_str = String(d_obj.getMinutes()).padStart(2, '0');
	return pretty_fn(iso_str) + ' at ' + h_str + ':' + m_str;
};

/*	Pipe separated, not comma, because the font list itself contains commas	*/
const pal_obj = {};
for (const part_str of String(cfg_obj.EMAIL_PALETTE || '').split('|'))
{
	const at_num = part_str.indexOf('=');
	if (at_num > 0) { pal_obj[part_str.slice(0, at_num).trim()] = part_str.slice(at_num + 1).trim(); }
}

/*	Palette tokens first, then the content, so a colour name appearing inside the body
	cannot be substituted twice	*/
const fill_fn = function (tpl_str, extra_obj)
{
	let s_str = String(tpl_str || '');
	for (const k_str of Object.keys(pal_obj)) { s_str = s_str.split('%%' + k_str + '%%').join(pal_obj[k_str]); }
	for (const k_str of Object.keys(extra_obj || {})) { s_str = s_str.split('%%' + k_str + '%%').join(extra_obj[k_str]); }
	return s_str;
};

const shell_fn = function (inner_str)
{
	return fill_fn(cfg_obj.EMAIL_SHELL, { BRAND: esc_fn(cfg_obj.BRAND_NAME), BODY: inner_str });
};

/*	A concluded request is anything that is not still waiting to be offered. Rows are kept
	per opportunity rather than per contact, so a decline or an expiry ends that request
	without condemning the person: re-adding them creates a new opportunity, which has no
	row, and therefore becomes a fresh candidate.	*/
const concluded_ary = ['offered', 'accepted', 'declined', 'expired', 'register_failed'];

for (const ev_obj of events_ary)
{
	const event_obj = ev_obj?.events?.edges?.[0]?.node;
	if (!event_obj) continue;
	const eid_str = event_obj.id;
	const title_str = event_obj.title;
	const start_str = event_obj.start ?? '';
	const deadline_str = event_obj.registrationDeadline;
	const max_num = Number(event_obj.maxPlaces ?? 0);
	/*	Filtered to isCancelled false in Fetch Event. Counting cancelled learners here
		would refuse every place freed by a cancellation, which is the main way one opens	*/
	const reg_num = Number(event_obj.learners?.pageInfo?.totalRecords ?? 0);
	if (deadline_str && DateTime.fromISO(deadline_str) < DateTime.fromISO(now_str)) continue;
	const erows_ary = rows_ary.filter(r_obj => r_obj.event_id === eid_str);

	/*	Keyed on opportunity, so one row is the history of one request	*/
	const byOpp_obj = {};
	for (const r_obj of erows_ary)
	{
		if (r_obj.opportunity_id) { byOpp_obj[r_obj.opportunity_id] = r_obj; }
	}

	/*	Per-contact guards. Keeping history per opportunity means one person could hold
		several rows on one event, so these stop them being offered or booked twice.	*/
	const contactOffered_obj = {};
	const contactAccepted_obj = {};
	for (const r_obj of erows_ary)
	{
		if (r_obj.status === 'offered') { contactOffered_obj[r_obj.contact_id] = true; }
		if (r_obj.status === 'accepted') { contactAccepted_obj[r_obj.contact_id] = true; }
	}

	/*	Counted from the rows rather than from candidates, so an outstanding offer still
		counts even if its interest has since moved off the waitlist step	*/
	const outstanding_num = erows_ary.filter(r_obj => r_obj.status === 'offered').length;

	const wl_ary = (event_obj.interests?.edges ?? []).map(e_obj => e_obj.node).filter(n_obj => n_obj?.opportunity?.step?.name === step_str && n_obj?.opportunity?.contact?.id);
	const view_ary = [];
	for (const n_obj of wl_ary)
	{
		const c_str = n_obj.opportunity.contact.id;
		const o_str = n_obj.opportunity.id;
		const ex_obj = byOpp_obj[o_str];
		const status_str = ex_obj?.status ?? 'new';

		/*	This request is already concluded	*/
		if (concluded_ary.indexOf(status_str) !== -1) continue;

		/*	They already hold a place on this event, or already have an offer open on it
			under another opportunity	*/
		if (contactAccepted_obj[c_str]) continue;
		if (contactOffered_obj[c_str]) continue;

		view_ary.push({ contact_id: c_str, opportunity_id: o_str, interest_id: n_obj.id, since_str: ex_obj?.waitlisted_since ?? now_str, is_new_bln: !ex_obj });
	}
	view_ary.sort((a_obj, b_obj) => String(a_obj.since_str).localeCompare(String(b_obj.since_str)));
	const avail_num = max_num - reg_num - outstanding_num;
	let offered_ct = 0;
	for (const v_obj of view_ary)
	{
		const do_offer_bln = (avail_num > 0) && (offered_ct < avail_num);
		if (!do_offer_bln && !v_obj.is_new_bln) continue;
		if (do_offer_bln)
		{
			offered_ct += 1;
			const token_str = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 12) + '-' + offered_ct;
			const exp_str = timeout_num > 0 ? DateTime.fromISO(now_str).plus({ hours: timeout_num }).toISO() : '';
			const resu_str = timeout_num > 0 ? exp_str : DateTime.fromISO(now_str).plus({ years: 10 }).toISO();

			/*	One link, to a page that writes nothing. Accept and decline are submit buttons
				there, so a mail scanner fetching this URL cannot answer on their behalf	*/
			const url_str = String(cfg_obj.RESPONSE_PAGE_URL) + '?token=' + token_str;
			const button_str = fill_fn(cfg_obj.EMAIL_BUTTON, { URL: url_str, LABEL: esc_fn(cfg_obj.EMAIL_BUTTON_LABEL) });

			const when_str = pretty_fn(start_str);
			const hold_str = exp_str
				? '<p style="margin:0 0 4px;padding-top:14px;border-top:1px solid ' + pal_obj.LINE + ';color:' + pal_obj.MUTED + ';font-size:13px;">This place is held for you until <strong style="color:' + pal_obj.INK + ';font-weight:600;">' + esc_fn(prettyTime_fn(exp_str)) + '</strong>. After that it passes to the next person on the waitlist.</p>'
				: '';

			const subj_str = String(cfg_obj.EMAIL_SUBJECT_TEMPLATE).split('{title}').join(title_str);

			const body_str = shell_fn(
				'<p style="margin:0 0 6px;color:' + pal_obj.MUTED + ';font-size:13px;">A place is available</p>'
				+ '<p style="margin:0 0 4px;font-size:20px;font-weight:600;color:' + pal_obj.DEEP + ';">' + esc_fn(title_str) + '</p>'
				+ (when_str ? '<p style="margin:0 0 18px;color:' + pal_obj.MUTED + ';font-size:14px;">' + esc_fn(when_str) + '</p>' : '<p style="margin:0 0 18px;"></p>')
				+ '<div style="background:' + pal_obj.TINT + ';border-left:3px solid ' + pal_obj.ACCENT + ';padding:12px 14px;margin:0 0 20px;">'
				+ '<p style="margin:0;">A place has opened on this course, and you are next on the waitlist.</p></div>'
				+ button_str
				+ '<p style="margin:0 0 18px;font-size:14px;color:' + pal_obj.MUTED + ';">You can accept or turn down the place on that page. Nothing is decided until you choose.</p>'
				+ hold_str);

			out_ary.push({ json: { event_id: eid_str, event_title: title_str, contact_id: v_obj.contact_id, opportunity_id: v_obj.opportunity_id, status: 'offered', token: token_str, waitlisted_since: v_obj.since_str, offered_at: now_str, expires_at: exp_str, updated_at: now_str, is_offer: true, interest_id: v_obj.interest_id, reservation_until: resu_str, subject: subj_str, body: body_str } });
		} else {
			out_ary.push({ json: { event_id: eid_str, event_title: title_str, contact_id: v_obj.contact_id, opportunity_id: v_obj.opportunity_id, status: 'waiting', token: '', waitlisted_since: v_obj.since_str, offered_at: '', expires_at: '', updated_at: now_str, is_offer: false, interest_id: v_obj.interest_id, reservation_until: '', subject: '', body: '' } });
		}
	}
}
return out_ary;

/*	Extract Offer Items - rejoin the rows this run actually claimed with their offer detail	*/
/*	Only claimed rows arrive here, so a run that lost the claim sends nothing rather than
	emailing a place another run already gave away. The row itself carries no subject, body,
	interest id or reservation time, so those come back from Plan Offers, matched on the
	opportunity, which is the key one row represents.	*/
const claimed_ary = $input.all();
const byOpp_obj = {};

for (const item_obj of $('Plan Offers').all())
{
	const opp_str = String(item_obj.json.opportunity_id ?? '');

	if (opp_str !== '' && item_obj.json.is_offer)
	{
		byOpp_obj[opp_str] = item_obj.json;
	}
}

const out_ary = [];

for (const row_obj of claimed_ary)
{
	/*	A losing claim can surface as an empty object rather than no item at all, so an
		unidentifiable row is dropped rather than trusted	*/
	const opp_str = String(row_obj.json?.opportunity_id ?? '');

	if (opp_str === '')
	{
		continue;
	}

	const plan_obj = byOpp_obj[opp_str];

	if (plan_obj === undefined)
	{
		continue;
	}

	out_ary.push({ json: Object.assign({}, plan_obj, { row_id: row_obj.json.id }) });
}

return out_ary;

