mutation ReserveWaitlistPlace($interestIds: [ID]!) {
  opportunities { reservePlacesForInterests(input: { interestIds: $interestIds }) { errors { label message value } } }
}

mutation ExtendWaitlistHold($opportunityId: ID!, $until: TimeZonedDateTime) {
  opportunities { extendReservations(input: { opportunityId: $opportunityId, reservationsValidUntil: $until }) { errors { label message value } } }
}

mutation SendWaitlistOffer($contactIds: [String]!, $subject: String, $body: String, $eventId: String, $sendingAddressId: ID) {
  bulkAdhocEmails { sendBulkContactAdhocEmail(input: { contactIds: $contactIds, subject: $subject, body: $body, eventId: $eventId, sendingAddressId: $sendingAddressId }) { errors { label message value } } }
}

mutation AddWaitlistLog($originIdentifier: String!, $nodeId: ID!, $message: String!, $status: ExternalLogTypeStatus!, $payload: String!) {
  externalLog { createExternalIntegrationLog(input: { originIdentifier: $originIdentifier, nodeId: $nodeId, message: $message, status: $status, payload: $payload }) { errors { label message value } } }
}

mutation AddWaitlistLog($originIdentifier: String!, $nodeId: ID!, $message: String!, $status: ExternalLogTypeStatus!, $payload: String!) {
  externalLog { createExternalIntegrationLog(input: { originIdentifier: $originIdentifier, nodeId: $nodeId, message: $message, status: $status, payload: $payload }) { errors { label message value } } }
}

mutation AddWaitlistLog($originIdentifier: String!, $nodeId: ID!, $message: String!, $status: ExternalLogTypeStatus!, $payload: String!) {
  externalLog { createExternalIntegrationLog(input: { originIdentifier: $originIdentifier, nodeId: $nodeId, message: $message, status: $status, payload: $payload }) { errors { label message value } } }
}

query VerifyWaitlistHold($opportunityId: String!) {
  opportunities(filters: [{ field: id, operation: eq, value: $opportunityId }]) {
    edges { node { id isReservationValid reservationsValidUntil } }
  }
}

