/*	Assemble the event from every interests page fetched by Fetch Event Pages	*/
const pages_ary = $input.all();
const byEvent_obj = {};

for (const page_obj of pages_ary)
{
	const edges_ary = page_obj.json?.data?.events?.edges ?? [];

	for (const edge_obj of edges_ary)
	{
		const event_obj = edge_obj.node ?? {};
		const eventId_str = String(event_obj.id ?? '');

		if (eventId_str === '')
		{
			continue;
		}

		if (byEvent_obj[eventId_str] === undefined)
		{
			byEvent_obj[eventId_str] = { event_obj: event_obj, interests_ary: [], expected_int: 0 };
		}

		const bucket_obj = byEvent_obj[eventId_str];
		const pageInfo_obj = event_obj.interests?.pageInfo ?? {};

		bucket_obj.expected_int = Number(pageInfo_obj.totalRecords ?? 0);
		bucket_obj.interests_ary = bucket_obj.interests_ary.concat(event_obj.interests?.edges ?? []);
	}
}

/*	Count the work. A short collection means the loop stopped early, and offering from a
	truncated candidate list would skip whoever was cut off without writing anything	*/
const out_ary = [];

for (const eventId_str of Object.keys(byEvent_obj))
{
	const bucket_obj = byEvent_obj[eventId_str];
	const collected_int = bucket_obj.interests_ary.length;

	if (collected_int < bucket_obj.expected_int)
	{
		throw new Error('Interest paging incomplete for ' + eventId_str + ': collected ' + collected_int + ' of ' + bucket_obj.expected_int);
	}

	const merged_obj = Object.assign({}, bucket_obj.event_obj);

	merged_obj.interests = { pageInfo: { totalRecords: bucket_obj.expected_int, hasNextPage: false }, edges: bucket_obj.interests_ary };
	out_ary.push({ json: { events: { edges: [{ node: merged_obj }] } } });
}

return out_ary;

/*	Select Offer Candidates - the people Plan Offers decided to offer, ahead of the claim	*/
/*	Reads Plan Offers directly rather than via pairing, so ordering after the upsert is safe	*/
const out_ary = [];

for (const item_obj of $('Plan Offers').all())
{
	if (item_obj.json.is_offer)
	{
		out_ary.push({ json: item_obj.json });
	}
}

return out_ary;
